'use client';

import { useEffect, useRef, useState, useSyncExternalStore } from 'react';
import type { ReactNode } from 'react';
import { selectTasks, taskFromUrl, taskReference, taskUrl, TASK_STATES } from '@hachej/boring-ui-kit/task-board';
import type { TaskFile, TaskFilter, TaskRecord, TaskState } from '@hachej/boring-ui-kit/task-board';
import { ArrowLeftIcon } from 'lucide-react';
import { Drawer, DrawerContent, DrawerTitle } from '@/components/ui/drawer';
import { Button } from '@/components/ui/button';
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from '@/components/ui/empty';
import { cn } from '../utils/utils';
import { TaskRequestCard, taskStateLabels } from './task-request-card';
import { TaskDetail } from './task-detail';
import type { TaskDetailProps } from './task-detail';

export { TaskRequestCard, TaskStatusChip } from './task-request-card';
export { TaskDetail } from './task-detail';
export type { TaskRequestCardProps } from './task-request-card';
export type { TaskDetailProps } from './task-detail';
export type { TaskFile, TaskRecord, TaskFilter, TaskState } from '@hachej/boring-ui-kit/task-board';

const navigation = 'boring:task-navigation';
const subscribe = (changed: () => void) => {
  window.addEventListener('popstate', changed); window.addEventListener(navigation, changed);
  return () => { window.removeEventListener('popstate', changed); window.removeEventListener(navigation, changed); };
};
const readSelection = () => taskFromUrl(window.location.href);
const serverSelection = () => null;

export interface TaskFileViewApi {
  readonly fullscreen: boolean;
  readonly onFullscreenChange: (fullscreen: boolean) => void;
  readonly onClose: () => void;
  readonly onBack: () => void;
  /** The host's PM pointing service; absent unless onShowFile was supplied. */
  readonly onShowFile?: (() => void) | undefined;
}
export interface TaskBoardProps {
  readonly tasks: readonly TaskRecord[];
  readonly filter?: TaskFilter;
  readonly currentUser?: string;
  readonly limit?: number;
  readonly variant?: 'board' | 'compact';
  readonly title?: string;
  readonly labels?: Readonly<Record<TaskState, string>>;
  /** Omit to use ?task= with native history. A router may instead supply controlled selection. */
  readonly selectedTask?: string | null;
  readonly onSelectedTaskChange?: ((id: string | null) => void) | undefined;
  /** Optional host navigation/present path, particularly for compact lists inside the PM panel. */
  readonly onOpen?: ((task: TaskRecord) => void) | undefined;
  readonly actions?: ((task: TaskRecord) => ReactNode) | undefined;
  readonly onAnswer?: TaskDetailProps['onAnswer'];
  readonly onOther?: TaskDetailProps['onOther'];
  readonly onDiscussQuestion?: TaskDetailProps['onDiscussQuestion'];
  /** Adapter paths only. The host reauthorizes them when opening the regular viewer. */
  readonly onOpenFile?: TaskDetailProps['onOpenFile'];
  readonly onShowFile?: TaskDetailProps['onOpenFile'];
  /** Supply the host's regular FileViewer in a wider overlay over task detail; no second store or composer. */
  readonly renderFile?: ((task: TaskRecord, file: TaskFile, api: TaskFileViewApi) => ReactNode) | undefined;
  /** Host-owned overlay appearance (for example the host's existing shadow token). */
  readonly overlayClassName?: string;
  readonly className?: string;
}

/** Authorized records in; container-responsive board beneath stacked shadcn task/file overlays. */
export function TaskBoard({ tasks, filter = 'all', currentUser, limit, variant = 'board', title = 'Tasks', labels = taskStateLabels,
  selectedTask, onSelectedTaskChange, onOpen, actions, onAnswer, onOther, onDiscussQuestion, onOpenFile, onShowFile, renderFile, overlayClassName, className }: TaskBoardProps) {
  const urlSelection = useSyncExternalStore(subscribe, readSelection, serverSelection);
  const selected = selectedTask === undefined ? onOpen ? null : urlSelection : selectedTask;
  const detail = selected === null ? undefined : tasks.find(task => task.id === selected || taskReference(task) === selected);
  const shown = selectTasks(tasks, { filter, ...(currentUser === undefined ? {} : { currentUser }), ...(limit === undefined ? {} : { limit }) });
  const [fileSelection, setFileSelection] = useState<{ readonly taskId: string; readonly path: string } | null>(null);
  const filePath = fileSelection?.path;
  const file = detail?.id === fileSelection?.taskId ? detail?.files?.find(candidate => candidate.path === filePath) : undefined;
  const fileOpen = !!file && !!renderFile;
  const [fileFullscreen, setFileFullscreen] = useState(false);
  const closeFile = () => { setFileSelection(null); setFileFullscreen(false); };
  const openFile = (task: TaskRecord, file: TaskFile) => { setFileSelection({ taskId: task.id, path: file.path }); onOpenFile?.(task, file); };
  const root = useRef<HTMLElement>(null);
  const back = useRef<HTMLButtonElement>(null);
  const previous = useRef<string | null>(null);
  useEffect(() => {
    if (selected !== null) back.current?.focus();
    else if (previous.current !== null) {
      const id = previous.current;
      const links = root.current?.querySelectorAll<HTMLAnchorElement>('[data-task-open]');
      const link = [...links ?? []].find(candidate => candidate.dataset['taskOpen'] === id);
      const folded = link?.closest('details');
      if (folded) folded.open = true;
      link?.focus();
    }
    previous.current = detail?.id ?? selected;
  }, [selected, detail?.id]);
  const select = (id: string | null) => {
    closeFile();
    if (selectedTask === undefined) {
      window.history.pushState(null, '', taskUrl(window.location.href, id));
      window.dispatchEvent(new Event(navigation));
    }
    onSelectedTaskChange?.(id);
  };
  const open = (task: TaskRecord) => { if (onOpen) onOpen(task); else select(task.id); };
  const href = (task: TaskRecord) => typeof window === 'undefined' ? `?task=${encodeURIComponent(task.id)}` : taskUrl(window.location.href, task.id);
  const card = (task: TaskRecord) => <TaskRequestCard key={task.id} task={task} variant={variant === 'compact' ? 'compact' : 'card'} selected={task.id === detail?.id} href={href(task)} onOpen={open} labels={labels} />;
  const empty = <Empty><EmptyHeader><EmptyTitle>No requests</EmptyTitle><EmptyDescription>No tasks match this view.</EmptyDescription></EmptyHeader></Empty>;
  return <section ref={root} data-boring="task-board" data-variant={variant} aria-label={title} className={cn('@container/task-board min-w-0', className)} onKeyDown={event => {
    if (event.key === 'Escape' && selected !== null && !event.defaultPrevented) { event.preventDefault(); if (fileOpen) closeFile(); else select(null); }
  }}>
    <Drawer open={selected !== null} onOpenChange={next => { if (!next) select(null); }} modal={false} swipeDirection="right">
      <div data-task-list className="@container/task-rails flex min-w-0 flex-col gap-4">
        {variant === 'compact' ? <div role="list" aria-label={title} className="flex flex-col gap-2">{shown.length ? shown.map(card) : empty}</div> : <>
          <div className="grid min-w-0 gap-4 @2xl/task-rails:grid-cols-3">
            {TASK_STATES.slice(0, 3).map(state => <section key={state} data-task-column={state} className="flex min-w-0 flex-col gap-3" aria-label={labels[state]}>
              <h3>{labels[state]} · {shown.filter(task => task.state === state).length}</h3>
              <div role="list" className="flex flex-col gap-2">{shown.filter(task => task.state === state).sort((a, b) => Number(b.waiting_on_you === true) - Number(a.waiting_on_you === true)).map(card)}</div>
              {!shown.some(task => task.state === state) && <p className="text-muted-foreground">No tasks</p>}
            </section>)}
          </div>
          {TASK_STATES.slice(3).map(state => <details key={state} data-task-column={state} className="min-w-0">
            <summary className="min-h-11 cursor-pointer content-center">{labels[state]} · {shown.filter(task => task.state === state).length}</summary>
            <div role="list" className="flex flex-col gap-2">{shown.filter(task => task.state === state).map(card)}</div>
          </details>)}
        </>}
      </div>
      <DrawerContent initialFocus={back} finalFocus={false} className={overlayClassName} style={{ '--drawer-content-width': 'min(100vw, 32rem)' } as React.CSSProperties}>
        <DrawerTitle className="sr-only">Task detail</DrawerTitle>
        <section aria-label="Task detail" data-task-side className="flex min-h-0 min-w-0 flex-1 flex-col gap-4 overflow-auto p-4" aria-live="polite">
          <Button ref={back} variant="outline" className="min-h-11 self-start" onClick={() => select(null)}><ArrowLeftIcon aria-hidden="true" />Back to tasks</Button>
          {detail ? <TaskDetail key={detail.id} task={detail} labels={labels} actions={actions?.(detail)} onAnswer={onAnswer} onOther={onOther} onDiscussQuestion={onDiscussQuestion} onOpenFile={renderFile || onOpenFile ? openFile : undefined} /> : <Empty><EmptyHeader><EmptyTitle>Task unavailable</EmptyTitle><EmptyDescription>The host has not supplied this task.</EmptyDescription></EmptyHeader></Empty>}
          <Drawer open={fileOpen} onOpenChange={next => { if (!next) closeFile(); }} modal={false} swipeDirection="right">
            <DrawerContent className={overlayClassName} style={{ '--drawer-content-width': fileFullscreen ? '100%' : 'min(100vw, 56rem)' } as React.CSSProperties}>
              <DrawerTitle className="sr-only">Task file viewer</DrawerTitle>
              {fileOpen && detail && file && <section aria-label="Task file viewer" data-task-file-pane={detail.id} className="h-dvh min-w-0 flex-1 overflow-hidden">
                {renderFile!(detail, file, { fullscreen: fileFullscreen, onFullscreenChange: setFileFullscreen, onClose: closeFile, onBack: closeFile, onShowFile: onShowFile ? () => onShowFile(detail, file) : undefined })}
              </section>}
            </DrawerContent>
          </Drawer>
        </section>
      </DrawerContent>
    </Drawer>
  </section>;
}

'use client';

import type { MouseEvent, ReactNode } from 'react';
import type { TaskRecord, TaskState } from '@hachej/boring-ui-kit/task-board';
import { taskReference } from '@hachej/boring-ui-kit/task-board';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Item, ItemContent, ItemDescription, ItemTitle } from '@/components/ui/item';

export const taskStateLabels: Readonly<Record<TaskState, string>> = { waiting: 'Waiting', working: 'Working', open: 'Open', done: 'Done', closed: 'Closed' };

export function TaskStatusChip({ task, labels = taskStateLabels }: { readonly task: Pick<TaskRecord, 'state' | 'status'>; readonly labels?: Readonly<Record<TaskState, string>> | undefined }) {
  return <Badge variant={task.state === 'working' ? 'default' : 'secondary'}>{task.status ?? labels[task.state]}</Badge>;
}
export interface TaskRequestCardProps {
  readonly task: TaskRecord;
  readonly variant?: 'card' | 'compact';
  readonly selected?: boolean;
  readonly href?: string;
  readonly onOpen?: ((task: TaskRecord) => void) | undefined;
  readonly actions?: ReactNode;
  readonly labels?: Readonly<Record<TaskState, string>> | undefined;
}

/** Shared by the board, detail and the PM's confirmation card; actions remain host-authorized. */
export function TaskRequestCard({ task, variant = 'card', selected, href, onOpen, actions, labels }: TaskRequestCardProps) {
  const activate = (event: MouseEvent<HTMLAnchorElement>) => {
    if (!onOpen || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) return;
    event.preventDefault(); onOpen(task);
  };
  const link = href ? <a href={href} onClick={activate} data-task-open={task.id} aria-current={selected ? 'true' : undefined} /> : undefined;
  const rowLink = variant === 'compact' || !actions;
  const title = link && !rowLink ? <Button variant="link" className="min-h-11 min-w-0 justify-start whitespace-normal text-start" render={link}>{task.title}</Button> : <span>{task.title}</span>;
  return <div role="listitem"><Item variant="outline" size="sm" className="min-h-11" data-task-card={task.id} data-selected={selected || undefined} {...(link && rowLink ? { render: link } : {})}>
    <ItemContent className="min-w-0">
      <ItemTitle className="min-w-0">{title}</ItemTitle>
      {variant !== 'compact' && <>
        <ItemDescription>{taskReference(task)}</ItemDescription>
        {(task.screen || task.capture) && <ItemDescription>{[task.screen, task.capture].filter(Boolean).join(' · ')}</ItemDescription>}
        {(task.waiting_on || task.risk === 'high') && <div className="flex flex-wrap gap-2">
          {task.waiting_on && <Badge variant={task.waiting_on_you ? 'default' : 'outline'}>{task.waiting_on_you ? 'Waiting on you' : `On ${task.waiting_on.who}`}</Badge>}
          {task.risk === 'high' && <Badge variant="outline">High risk</Badge>}
        </div>}
      </>}
    </ItemContent>
    <TaskStatusChip task={task} labels={labels} />
    {variant !== 'compact' && actions && <div className="flex w-full flex-wrap gap-2">{actions}</div>}
  </Item></div>;
}

'use client';

import { useState } from 'react';
import type { ReactNode } from 'react';
import { ChevronDownIcon, ChevronUpIcon } from 'lucide-react';
import type { TaskFile, TaskQuestion, TaskRecord, TaskState } from '@hachej/boring-ui-kit/task-board';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Item, ItemContent, ItemDescription, ItemTitle } from '@/components/ui/item';
import { TaskRequestCard } from './task-request-card';

export interface TaskDetailProps {
  readonly task: TaskRecord;
  readonly labels?: Readonly<Record<TaskState, string>> | undefined;
  readonly actions?: ReactNode;
  /** The host reauthorizes and resolves the original question. Rendering never supplies approval. */
  readonly onAnswer?: ((task: TaskRecord, question: TaskQuestion, value: string) => void) | undefined;
  /** Opens the host's free-answer flow; no synthetic option value or approval is generated. */
  readonly onOther?: ((task: TaskRecord, question: TaskQuestion) => void) | undefined;
  readonly onDiscussQuestion?: ((task: TaskRecord, question: TaskQuestion) => void) | undefined;
  readonly onOpenFile?: ((task: TaskRecord, file: TaskFile) => void) | undefined;
}
const preview = (value: string) => value.length > 160 ? `${value.slice(0, 160)}…` : value;

function AnsweredQuestion({ question }: { readonly question: TaskQuestion }) {
  const [expanded, setExpanded] = useState(false);
  return <li data-task-answered={question.id} className="min-w-0">
    <Button variant="ghost" className="h-auto w-full min-w-0 justify-between text-start" aria-expanded={expanded} onClick={() => setExpanded(value => !value)}>
      <span className="flex min-w-0 flex-1 flex-col"><span className="truncate">{preview(question.text)}</span><span data-task-answer={question.id} className="truncate text-muted-foreground">{question.answeredBy ? `${preview(question.answeredBy)}: ` : ''}{preview(question.answer ?? '')}</span></span>
      {expanded ? <ChevronUpIcon className="shrink-0" aria-hidden="true" /> : <ChevronDownIcon className="shrink-0" aria-hidden="true" />}
    </Button>
    {expanded && <div data-task-answer-full className="whitespace-pre-wrap break-words p-3"><p>{question.text}</p><p>{question.answeredBy && <>{question.answeredBy}: </>}{question.answer}</p></div>}
  </li>;
}

export function TaskDetail({ task, labels, actions, onAnswer, onOther, onDiscussQuestion, onOpenFile }: TaskDetailProps) {
  const [showAll, setShowAll] = useState(false);
  const answered = task.questions?.filter(question => question.answer !== undefined).toReversed().sort((a, b) => (Date.parse(b.answeredAt ?? '') || 0) - (Date.parse(a.answeredAt ?? '') || 0)) ?? [];
  return <div className="flex min-w-0 flex-col gap-4" data-task-detail={task.id}>
    <div role="list"><TaskRequestCard task={task} labels={labels} actions={actions} /></div>
    {task.spec && <p className="whitespace-pre-wrap break-words">{task.spec}</p>}
    {task.waiting_on?.question && <Item variant="outline"><ItemContent><ItemTitle>Waiting on {task.waiting_on.who}</ItemTitle><ItemDescription>{task.waiting_on.question}</ItemDescription></ItemContent></Item>}
    {!!task.questions?.length && <h3>Questions</h3>}
    {task.questions?.filter(question => question.answer === undefined).map(question => <Item variant="outline" key={question.id} data-task-question={question.id}>
      <ItemContent className="min-w-0"><ItemTitle>{question.text}</ItemTitle>
        <div className="flex flex-wrap gap-2">
          {question.options?.map((option, index) => {
            const value = typeof option === 'string' ? option : option.value;
            const label = typeof option === 'string' ? option : option.label;
            return onAnswer ? <Button key={index} variant={index === 0 ? 'default' : 'outline'} className="min-h-11 whitespace-normal" onClick={() => onAnswer(task, question, value)}>{label}</Button> : <Badge key={index} variant="outline">{label}</Badge>;
          })}
          {onOther && <Button variant="outline" className="min-h-11" data-task-other={question.id} onClick={() => onOther(task, question)}>Other…</Button>}
        </div>
        {onDiscussQuestion && <Button variant="link" className="self-start" data-task-discuss={question.id} onClick={() => onDiscussQuestion(task, question)}>Discuss in chat</Button>}
      </ItemContent>
    </Item>)}
    {!!answered.length && <section aria-label="Answered questions" className="flex min-w-0 flex-col gap-2"><h3>Answered · {answered.length}</h3>
      <ul className="flex min-w-0 flex-col gap-2">{(showAll ? answered : answered.slice(0, 3)).map(question => <AnsweredQuestion key={question.id} question={question} />)}</ul>
      {answered.length > 3 && <Button variant="link" className="self-start" data-task-show-answers onClick={() => setShowAll(value => !value)}>{showAll ? 'Show latest 3' : `Show all ${answered.length}`}</Button>}
    </section>}
    {!!task.files?.length && <section aria-label="Task files" className="flex min-w-0 flex-col gap-2"><h3>Files</h3>
      {task.files.map(file => onOpenFile ? <Button key={file.path} variant="outline" className="min-h-11 justify-start whitespace-normal break-all" data-task-file={file.path} onClick={() => onOpenFile(task, file)}>{file.name ?? file.path.split('/').pop()}</Button> : <p key={file.path} className="break-all">{file.name ?? file.path}</p>)}
    </section>}
    {!!task.history?.length && <section aria-label="Task history" className="flex flex-col gap-3"><h3>History</h3><ol className="flex flex-col gap-3">
      {task.history.map((entry, index) => <li key={entry.id ?? index} className="break-words"><p>{entry.note}</p><p className="text-muted-foreground">{entry.actor}{entry.at && <> · <time dateTime={entry.at}>{entry.at}</time></>}</p></li>)}
    </ol></section>}
  </div>;
}
